package store

import (
	"encoding/json"
	"time"

	"example.com/tally/internal/money"
)

// OrgPlan is the Tally plan an organization pays for.
type OrgPlan string

// Tally's own plans.
const (
	OrgFree     OrgPlan = "free"
	OrgTeam     OrgPlan = "team"
	OrgBusiness OrgPlan = "business"
)

// Valid reports whether p is a known plan.
func (p OrgPlan) Valid() bool { return p == OrgFree || p == OrgTeam || p == OrgBusiness }

// Org is a tenant: a company that bills its customers through Tally.
type Org struct {
	ID       string  `json:"id"`
	Name     string  `json:"name"`
	Plan     OrgPlan `json:"plan"`
	TimeZone string  `json:"time_zone"` // IANA name, for example "Europe/Berlin"
	// TaxRateBP is the tax rate charged on the organization's invoices, in basis points (1% = 100).
	TaxRateBP int       `json:"tax_rate_bp"`
	CreatedAt time.Time `json:"created_at"`
}

// User is a person who can sign in. A user can belong to several organizations.
type User struct {
	ID        string    `json:"id"`
	Email     string    `json:"email"`
	Name      string    `json:"name"`
	CreatedAt time.Time `json:"created_at"`
}

// Role is what a member may do in an organization.
type Role string

// Roles.
const (
	RoleOwner   Role = "owner"
	RoleAdmin   Role = "admin"
	RoleBilling Role = "billing"
	RoleMember  Role = "member"
	RoleViewer  Role = "viewer"
)

// Valid reports whether r is a known role.
func (r Role) Valid() bool {
	switch r {
	case RoleOwner, RoleAdmin, RoleBilling, RoleMember, RoleViewer:
		return true
	}
	return false
}

// Member is a user's membership of an organization.
type Member struct {
	OrgID     string    `json:"org_id"`
	UserID    string    `json:"user_id"`
	Role      Role      `json:"role"`
	CreatedAt time.Time `json:"created_at"`
}

// APIKey lets a member call the API. It acts as that member, with the member's current role.
type APIKey struct {
	ID         string     `json:"id"`
	OrgID      string     `json:"org_id"`
	UserID     string     `json:"user_id"`
	Name       string     `json:"name"`
	Token      string     `json:"token"`
	CreatedAt  time.Time  `json:"created_at"`
	LastUsedAt *time.Time `json:"last_used_at,omitempty"`
	RevokedAt  *time.Time `json:"revoked_at,omitempty"`
}

// Invite asks someone to join an organization. Its token is sent to the invited address.
type Invite struct {
	ID         string     `json:"id"`
	OrgID      string     `json:"org_id"`
	Email      string     `json:"email"`
	Role       Role       `json:"role"`
	Token      string     `json:"token"`
	InvitedBy  string     `json:"invited_by"`
	CreatedAt  time.Time  `json:"created_at"`
	AcceptedAt *time.Time `json:"accepted_at,omitempty"`
	RevokedAt  *time.Time `json:"revoked_at,omitempty"`
}

// Customer is one of an organization's customers.
type Customer struct {
	ID    string `json:"id"`
	OrgID string `json:"org_id"`
	Name  string `json:"name"`
	Email string `json:"email"`
	// DefaultPaymentMethod is charged for renewals ("pm_..."); empty means invoices wait to be paid by hand.
	DefaultPaymentMethod string            `json:"default_payment_method,omitempty"`
	Metadata             map[string]string `json:"metadata,omitempty"`
	CreatedAt            time.Time         `json:"created_at"`
}

// Interval is how often a plan bills.
type Interval string

// Intervals.
const (
	Monthly Interval = "month"
	Yearly  Interval = "year"
)

// UsageType says what a plan charges for.
type UsageType string

// Usage types.
const (
	// Licensed plans charge UnitAmount per seat (the subscription's quantity) at the start of each period.
	Licensed UsageType = "licensed"
	// Metered plans charge UnitAmount per unit of reported usage at the end of each period.
	Metered UsageType = "metered"
)

// Plan is something an organization sells to its customers.
type Plan struct {
	ID         string         `json:"id"`
	OrgID      string         `json:"org_id"`
	Name       string         `json:"name"`
	Currency   money.Currency `json:"currency"`
	UnitAmount int64          `json:"unit_amount"` // minor units
	Interval   Interval       `json:"interval"`
	UsageType  UsageType      `json:"usage_type"`
	TrialDays  int            `json:"trial_days"`
	Active     bool           `json:"active"`
	CreatedAt  time.Time      `json:"created_at"`
}

// SubStatus is a subscription's state.
type SubStatus string

// Subscription states.
const (
	Trialing SubStatus = "trialing"
	Active   SubStatus = "active"
	PastDue  SubStatus = "past_due"
	Canceled SubStatus = "canceled"
)

// Subscription is a customer's subscription to a plan.
type Subscription struct {
	ID              string    `json:"id"`
	OrgID           string    `json:"org_id"`
	CustomerID      string    `json:"customer_id"`
	PlanID          string    `json:"plan_id"`
	Quantity        int       `json:"quantity"`
	Status          SubStatus `json:"status"`
	DiscountPercent int       `json:"discount_percent"`
	// StartedAt is when the subscription began; its billing periods are counted from it.
	StartedAt          time.Time  `json:"started_at"`
	CurrentPeriodStart time.Time  `json:"current_period_start"`
	CurrentPeriodEnd   time.Time  `json:"current_period_end"`
	TrialEnd           *time.Time `json:"trial_end,omitempty"`
	CancelAtPeriodEnd  bool       `json:"cancel_at_period_end"`
	CanceledAt         *time.Time `json:"canceled_at,omitempty"`
	CreatedAt          time.Time  `json:"created_at"`
}

// Line is one line of an invoice. A negative UnitAmount is a credit.
type Line struct {
	Description string `json:"description"`
	Quantity    int64  `json:"quantity"`
	UnitAmount  int64  `json:"unit_amount"`
}

// Amount is the line's quantity times its unit amount.
func (l Line) Amount() int64 { return l.Quantity * l.UnitAmount }

// InvoiceStatus is an invoice's state.
type InvoiceStatus string

// Invoice states.
const (
	InvoiceOpen InvoiceStatus = "open"
	InvoicePaid InvoiceStatus = "paid"
	InvoiceVoid InvoiceStatus = "void"
)

// Invoice is a bill to a customer.
type Invoice struct {
	ID              string         `json:"id"`
	OrgID           string         `json:"org_id"`
	CustomerID      string         `json:"customer_id"`
	SubscriptionID  string         `json:"subscription_id,omitempty"`
	Currency        money.Currency `json:"currency"`
	Lines           []Line         `json:"lines"`
	DiscountPercent int            `json:"discount_percent"`
	TaxRateBP       int            `json:"tax_rate_bp"`
	Status          InvoiceStatus  `json:"status"`
	PeriodStart     *time.Time     `json:"period_start,omitempty"`
	PeriodEnd       *time.Time     `json:"period_end,omitempty"`
	CreatedAt       time.Time      `json:"created_at"`
	PaidAt          *time.Time     `json:"paid_at,omitempty"`
	VoidedAt        *time.Time     `json:"voided_at,omitempty"`
}

// PaymentStatus is a payment attempt's result.
type PaymentStatus string

// Payment results.
const (
	PaymentSucceeded PaymentStatus = "succeeded"
	PaymentFailed    PaymentStatus = "failed"
)

// Payment is one attempt to charge an invoice.
type Payment struct {
	ID          string         `json:"id"`
	OrgID       string         `json:"org_id"`
	InvoiceID   string         `json:"invoice_id"`
	Amount      int64          `json:"amount"`
	Currency    money.Currency `json:"currency"`
	Status      PaymentStatus  `json:"status"`
	FailureCode string         `json:"failure_code,omitempty"`
	GatewayRef  string         `json:"gateway_ref,omitempty"`
	CreatedAt   time.Time      `json:"created_at"`
}

// UsageRecord is usage reported for a subscription to a metered plan.
type UsageRecord struct {
	ID             string    `json:"id"`
	OrgID          string    `json:"org_id"`
	SubscriptionID string    `json:"subscription_id"`
	Quantity       int64     `json:"quantity"`
	At             time.Time `json:"at"`
	CreatedAt      time.Time `json:"created_at"`
}

// WebhookEndpoint is a URL of the organization's that receives events.
type WebhookEndpoint struct {
	ID     string   `json:"id"`
	OrgID  string   `json:"org_id"`
	URL    string   `json:"url"`
	Events []string `json:"events"` // event types, or "*" for all
	// Secret signs the deliveries (webhooks.Sign).
	Secret         string    `json:"secret"`
	Enabled        bool      `json:"enabled"`
	DisabledReason string    `json:"disabled_reason,omitempty"`
	CreatedAt      time.Time `json:"created_at"`
}

// Event is something that happened in an organization, sent to its webhook endpoints.
type Event struct {
	ID        string          `json:"id"`
	OrgID     string          `json:"org_id"`
	Type      string          `json:"type"`
	Data      json.RawMessage `json:"data"`
	CreatedAt time.Time       `json:"created_at"`
}

// DeliveryStatus is a webhook delivery's state.
type DeliveryStatus string

// Delivery states.
const (
	DeliveryPending   DeliveryStatus = "pending"
	DeliverySucceeded DeliveryStatus = "succeeded"
	DeliveryFailed    DeliveryStatus = "failed"
)

// Delivery is the sending of one event to one endpoint.
type Delivery struct {
	ID             string         `json:"id"`
	OrgID          string         `json:"org_id"`
	EndpointID     string         `json:"endpoint_id"`
	EventID        string         `json:"event_id"`
	Status         DeliveryStatus `json:"status"`
	Attempts       int            `json:"attempts"`
	NextAttemptAt  *time.Time     `json:"next_attempt_at,omitempty"`
	LastAttemptAt  *time.Time     `json:"last_attempt_at,omitempty"`
	ResponseStatus int            `json:"response_status,omitempty"`
	Error          string         `json:"error,omitempty"`
	CreatedAt      time.Time      `json:"created_at"`
}
package store

import (
	"fmt"
	"sort"
)

// State is everything a store holds, for snapshots (package snapshot). Slices are sorted by ID.
type State struct {
	Seq              int               `json:"seq"`
	Orgs             []Org             `json:"orgs"`
	Users            []User            `json:"users"`
	Members          []Member          `json:"members"`
	APIKeys          []APIKey          `json:"api_keys"`
	Invites          []Invite          `json:"invites"`
	Customers        []Customer        `json:"customers"`
	Plans            []Plan            `json:"plans"`
	Subscriptions    []Subscription    `json:"subscriptions"`
	Usage            []UsageRecord     `json:"usage"`
	Invoices         []Invoice         `json:"invoices"`
	Payments         []Payment         `json:"payments"`
	WebhookEndpoints []WebhookEndpoint `json:"webhook_endpoints"`
	Events           []Event           `json:"events"`
	Deliveries       []Delivery        `json:"deliveries"`
}

// Export returns a copy of everything in the store.
func (s *Store) Export() State {
	s.mu.Lock()
	defer s.mu.Unlock()
	st := State{Seq: s.seq}
	for _, o := range s.orgs {
		st.Orgs = append(st.Orgs, o)
	}
	for _, u := range s.users {
		st.Users = append(st.Users, u)
	}
	for _, m := range s.members {
		st.Members = append(st.Members, m)
	}
	for _, k := range s.apiKeys {
		st.APIKeys = append(st.APIKeys, k)
	}
	for _, i := range s.invites {
		st.Invites = append(st.Invites, i)
	}
	for _, c := range s.customers {
		st.Customers = append(st.Customers, copyCustomer(c))
	}
	for _, p := range s.plans {
		st.Plans = append(st.Plans, p)
	}
	for _, sub := range s.subs {
		st.Subscriptions = append(st.Subscriptions, copySub(sub))
	}
	st.Usage = append(st.Usage, s.usage...)
	for _, inv := range s.invoices {
		st.Invoices = append(st.Invoices, copyInvoice(inv))
	}
	for _, p := range s.payments {
		st.Payments = append(st.Payments, p)
	}
	for _, ep := range s.endpoints {
		st.WebhookEndpoints = append(st.WebhookEndpoints, copyEndpoint(ep))
	}
	for _, e := range s.events {
		st.Events = append(st.Events, e)
	}
	for _, d := range s.delivs {
		st.Deliveries = append(st.Deliveries, copyDelivery(d))
	}
	sort.Slice(st.Orgs, func(i, j int) bool { return st.Orgs[i].ID < st.Orgs[j].ID })
	sort.Slice(st.Users, func(i, j int) bool { return st.Users[i].ID < st.Users[j].ID })
	sort.Slice(st.Members, func(i, j int) bool {
		if st.Members[i].OrgID != st.Members[j].OrgID {
			return st.Members[i].OrgID < st.Members[j].OrgID
		}
		return st.Members[i].UserID < st.Members[j].UserID
	})
	sort.Slice(st.APIKeys, func(i, j int) bool { return st.APIKeys[i].ID < st.APIKeys[j].ID })
	sort.Slice(st.Invites, func(i, j int) bool { return st.Invites[i].ID < st.Invites[j].ID })
	sort.Slice(st.Customers, func(i, j int) bool { return st.Customers[i].ID < st.Customers[j].ID })
	sort.Slice(st.Plans, func(i, j int) bool { return st.Plans[i].ID < st.Plans[j].ID })
	sort.Slice(st.Subscriptions, func(i, j int) bool { return st.Subscriptions[i].ID < st.Subscriptions[j].ID })
	sort.Slice(st.Usage, func(i, j int) bool { return st.Usage[i].ID < st.Usage[j].ID })
	sort.Slice(st.Invoices, func(i, j int) bool { return st.Invoices[i].ID < st.Invoices[j].ID })
	sort.Slice(st.Payments, func(i, j int) bool { return st.Payments[i].ID < st.Payments[j].ID })
	sort.Slice(st.WebhookEndpoints, func(i, j int) bool { return st.WebhookEndpoints[i].ID < st.WebhookEndpoints[j].ID })
	sort.Slice(st.Events, func(i, j int) bool { return st.Events[i].ID < st.Events[j].ID })
	sort.Slice(st.Deliveries, func(i, j int) bool { return st.Deliveries[i].ID < st.Deliveries[j].ID })
	return st
}

// FromState builds a store holding st.
func FromState(st State) (*Store, error) {
	s := New()
	s.seq = st.Seq
	dup := func(kind, id string, seen map[string]bool) error {
		if id == "" || seen[id] {
			return fmt.Errorf("%w: %s %q is missing or repeated", ErrInvalid, kind, id)
		}
		seen[id] = true
		return nil
	}
	seen := map[string]bool{}
	for _, o := range st.Orgs {
		if err := dup("organization", o.ID, seen); err != nil {
			return nil, err
		}
		s.orgs[o.ID] = o
	}
	for _, u := range st.Users {
		if err := dup("user", u.ID, seen); err != nil {
			return nil, err
		}
		s.users[u.ID] = u
		s.usersByEmail[normEmail(u.Email)] = u.ID
	}
	for _, m := range st.Members {
		if _, ok := s.orgs[m.OrgID]; !ok {
			return nil, fmt.Errorf("%w: member of unknown organization %q", ErrInvalid, m.OrgID)
		}
		if _, ok := s.users[m.UserID]; !ok {
			return nil, fmt.Errorf("%w: member is unknown user %q", ErrInvalid, m.UserID)
		}
		s.members[memberKey{m.OrgID, m.UserID}] = m
	}
	for _, k := range st.APIKeys {
		if err := dup("API key", k.ID, seen); err != nil {
			return nil, err
		}
		s.apiKeys[k.ID] = k
		if k.Token != "" {
			s.keysByToken[k.Token] = k.ID
		}
	}
	for _, i := range st.Invites {
		if err := dup("invite", i.ID, seen); err != nil {
			return nil, err
		}
		s.invites[i.ID] = i
	}
	for _, c := range st.Customers {
		if err := dup("customer", c.ID, seen); err != nil {
			return nil, err
		}
		s.customers[c.ID] = copyCustomer(c)
		s.customersByEmail[normEmail(c.Email)] = c.ID
	}
	for _, p := range st.Plans {
		if err := dup("plan", p.ID, seen); err != nil {
			return nil, err
		}
		s.plans[p.ID] = p
	}
	for _, sub := range st.Subscriptions {
		if err := dup("subscription", sub.ID, seen); err != nil {
			return nil, err
		}
		s.subs[sub.ID] = copySub(sub)
	}
	s.usage = append(s.usage, st.Usage...)
	for _, inv := range st.Invoices {
		if err := dup("invoice", inv.ID, seen); err != nil {
			return nil, err
		}
		s.invoices[inv.ID] = copyInvoice(inv)
	}
	for _, p := range st.Payments {
		if err := dup("payment", p.ID, seen); err != nil {
			return nil, err
		}
		s.payments[p.ID] = p
	}
	for _, ep := range st.WebhookEndpoints {
		if err := dup("webhook endpoint", ep.ID, seen); err != nil {
			return nil, err
		}
		s.endpoints[ep.ID] = copyEndpoint(ep)
	}
	for _, e := range st.Events {
		if err := dup("event", e.ID, seen); err != nil {
			return nil, err
		}
		s.events[e.ID] = e
	}
	for _, d := range st.Deliveries {
		if err := dup("delivery", d.ID, seen); err != nil {
			return nil, err
		}
		s.delivs[d.ID] = copyDelivery(d)
	}
	return s, nil
}
package api

import (
	"errors"
	"fmt"
	"net/http"
	"strings"

	"example.com/tally/internal/auth"
	"example.com/tally/internal/billing"
	"example.com/tally/internal/money"
	"example.com/tally/internal/payments"
	"example.com/tally/internal/store"
)

// invoiceView is an invoice as the API shows it: with its totals, a one-line description and its customer.
type invoiceView struct {
	store.Invoice
	billing.Totals
	TotalFormatted string       `json:"total_formatted"`
	Description    string       `json:"description"`
	Customer       *customerRef `json:"customer"`
}

// customerRef is the customer shown on an invoice; null when the customer was deleted.
type customerRef struct {
	ID    string `json:"id"`
	Name  string `json:"name"`
	Email string `json:"email"`
}

func newInvoiceView(inv store.Invoice, c *store.Customer) invoiceView {
	t := billing.Compute(inv)
	v := invoiceView{Invoice: inv, Totals: t, TotalFormatted: money.Format(t.Total, inv.Currency), Description: describe(inv.Lines)}
	if c != nil {
		v.Customer = &customerRef{ID: c.ID, Name: c.Name, Email: c.Email}
	}
	return v
}

// describe is the invoice's first line, and how many more there are.
func describe(lines []store.Line) string {
	d := lines[0].Description
	if len(lines) > 1 {
		d += fmt.Sprintf(" and %d more", len(lines)-1)
	}
	return d
}

func (s *Server) viewInvoice(inv store.Invoice) invoiceView {
	if c, ok := s.store.Customer(inv.OrgID, inv.CustomerID); ok {
		return newInvoiceView(inv, &c)
	}
	return newInvoiceView(inv, nil)
}

func findCustomer(cs []store.Customer, id string) *store.Customer {
	for i := range cs {
		if cs[i].ID == id {
			return &cs[i]
		}
	}
	return nil
}

func invoiceViewKey(v invoiceView) cursor { return cursor{T: v.CreatedAt, ID: v.ID} }

// listInvoices lists the organization's invoices, oldest first, optionally only those of ?customer_id=, ?subscription_id=
// or with ?status=.
func (s *Server) listInvoices(w http.ResponseWriter, r *http.Request, p auth.Principal) {
	pg, ok := parsePage(w, r)
	if !ok {
		return
	}
	q := r.URL.Query()
	status := store.InvoiceStatus(q.Get("status"))
	if status != "" && status != store.InvoiceOpen && status != store.InvoicePaid && status != store.InvoiceVoid {
		writeError(w, http.StatusBadRequest, "invalid_status", "status is open, paid or void")
		return
	}
	invs := s.store.ListInvoices(p.OrgID, store.InvoiceFilter{CustomerID: q.Get("customer_id"), SubscriptionID: q.Get("subscription_id"), Status: status})
	customers := s.store.Customers(p.OrgID)
	views := make([]invoiceView, 0, len(invs))
	for _, inv := range invs {
		views = append(views, newInvoiceView(inv, findCustomer(customers, inv.CustomerID)))
	}
	items, next := pageOf(views, invoiceViewKey, pg)
	writeJSON(w, http.StatusOK, list{Items: items, NextCursor: next})
}

func (s *Server) createInvoice(w http.ResponseWriter, r *http.Request, p auth.Principal) {
	var in struct {
		CustomerID      string         `json:"customer_id"`
		Currency        money.Currency `json:"currency"`
		Lines           []store.Line   `json:"lines"`
		DiscountPercent int            `json:"discount_percent"`
	}
	if !decode(w, r, &in) {
		return
	}
	if len(in.Lines) == 0 {
		writeError(w, http.StatusUnprocessableEntity, "invalid", "an invoice needs at least one line")
		return
	}
	for _, l := range in.Lines {
		if strings.TrimSpace(l.Description) == "" || l.Quantity <= 0 || l.UnitAmount < 0 {
			writeError(w, http.StatusUnprocessableEntity, "invalid", "each line needs a description, a positive quantity and a unit amount that is not negative")
			return
		}
	}
	inv, err := s.store.CreateInvoice(store.Invoice{OrgID: p.OrgID, CustomerID: in.CustomerID, Currency: in.Currency, Lines: in.Lines, DiscountPercent: in.DiscountPercent}, s.clock.Now())
	if err != nil {
		if errors.Is(err, store.ErrCustomerOrgMismatch) {
			writeError(w, http.StatusUnprocessableEntity, "customer_org_mismatch", fmt.Sprintf("customer %s belongs to another organization", in.CustomerID))
			return
		}
		s.storeError(w, err)
		return
	}
	s.publish(r.Context(), p.OrgID, "invoice.created", map[string]any{"invoice_id": inv.ID})
	writeJSON(w, http.StatusCreated, s.viewInvoice(inv))
}

func (s *Server) getInvoice(w http.ResponseWriter, r *http.Request, p auth.Principal) {
	inv, ok := s.store.Invoice(p.OrgID, r.PathValue("id"))
	if !ok {
		writeError(w, http.StatusNotFound, "not_found", "no such invoice")
		return
	}
	writeJSON(w, http.StatusOK, s.viewInvoice(inv))
}

// getInvoiceLines answers an invoice's lines with each line's amount, for the dashboard's invoice table.
func (s *Server) getInvoiceLines(w http.ResponseWriter, r *http.Request, p auth.Principal) {
	inv, ok := s.store.InvoiceByID(r.PathValue("id"))
	if !ok {
		writeError(w, http.StatusNotFound, "not_found", "no such invoice")
		return
	}
	type lineView struct {
		store.Line
		Amount int64 `json:"amount"`
	}
	items := []lineView{}
	for _, l := range inv.Lines {
		items = append(items, lineView{Line: l, Amount: l.Amount()})
	}
	writeJSON(w, http.StatusOK, list{Items: items})
}

// payInvoice charges an invoice: {"payment_method": "pm_..."}, or the customer's default payment method when it is absent.
func (s *Server) payInvoice(w http.ResponseWriter, r *http.Request, p auth.Principal) {
	var in struct {
		PaymentMethod string `json:"payment_method"`
	}
	if r.ContentLength != 0 && !decode(w, r, &in) {
		return
	}
	inv, pay, err := s.pay.Pay(r.Context(), p.OrgID, r.PathValue("id"), in.PaymentMethod)
	if err != nil {
		s.payError(w, err)
		return
	}
	writeJSON(w, http.StatusOK, map[string]any{"invoice": s.viewInvoice(inv), "payment": pay})
}

func (s *Server) payError(w http.ResponseWriter, err error) {
	var decline *payments.DeclineError
	switch {
	case errors.As(err, &decline):
		writeJSON(w, http.StatusPaymentRequired, map[string]string{"error": "payment_declined", "decline_code": decline.Code, "message": err.Error()})
	case errors.Is(err, payments.ErrAlreadyPaid):
		writeError(w, http.StatusConflict, "already_paid", err.Error())
	case errors.Is(err, payments.ErrInvoiceVoid):
		writeError(w, http.StatusConflict, "invoice_void", err.Error())
	case errors.Is(err, payments.ErrNoPaymentMethod):
		writeError(w, http.StatusUnprocessableEntity, "no_payment_method", err.Error())
	case errors.Is(err, payments.ErrUnavailable):
		writeError(w, http.StatusServiceUnavailable, "gateway_unavailable", "the payment gateway is unavailable; nothing was charged, try again")
	default:
		s.storeError(w, err)
	}
}

func (s *Server) voidInvoice(w http.ResponseWriter, r *http.Request, p auth.Principal) {
	now := s.clock.Now()
	inv, err := s.store.UpdateInvoice(p.OrgID, r.PathValue("id"), func(inv *store.Invoice) error {
		switch inv.Status {
		case store.InvoicePaid:
			return payments.ErrAlreadyPaid
		case store.InvoiceVoid:
			return payments.ErrInvoiceVoid
		}
		inv.Status, inv.VoidedAt = store.InvoiceVoid, &now
		return nil
	})
	if err != nil {
		s.payError(w, err)
		return
	}
	s.publish(r.Context(), p.OrgID, "invoice.voided", map[string]any{"invoice_id": inv.ID})
	writeJSON(w, http.StatusOK, s.viewInvoice(inv))
}

func (s *Server) listPayments(w http.ResponseWriter, r *http.Request, p auth.Principal) {
	writeJSON(w, http.StatusOK, list{Items: s.store.Payments(p.OrgID, r.URL.Query().Get("invoice_id"))})
}

package store

import (
	"encoding/json"
	"time"

	"example.com/tally/internal/money"
)

// OrgPlan is the Tally plan an organization pays for.
type OrgPlan string

// Tally's own plans.
const (
	OrgFree     OrgPlan = "free"
	OrgTeam     OrgPlan = "team"
	OrgBusiness OrgPlan = "business"
)

// Valid reports whether p is a known plan.
func (p OrgPlan) Valid() bool { return p == OrgFree || p == OrgTeam || p == OrgBusiness }

// Org is a tenant: a company that bills its customers through Tally.
type Org struct {
	ID       string  `json:"id"`
	Name     string  `json:"name"`
	Plan     OrgPlan `json:"plan"`
	TimeZone string  `json:"time_zone"` // IANA name, for example "Europe/Berlin"
	// TaxRateBP is the tax rate charged on the organization's invoices, in basis points (1% = 100).
	TaxRateBP int       `json:"tax_rate_bp"`
	CreatedAt time.Time `json:"created_at"`
}

// User is a person who can sign in. A user can belong to several organizations.
type User struct {
	ID        string    `json:"id"`
	Email     string    `json:"email"`
	Name      string    `json:"name"`
	CreatedAt time.Time `json:"created_at"`
}

// Role is what a member may do in an organization.
type Role string

// Roles.
const (
	RoleOwner   Role = "owner"
	RoleAdmin   Role = "admin"
	RoleBilling Role = "billing"
	RoleMember  Role = "member"
	RoleViewer  Role = "viewer"
)

// Valid reports whether r is a known role.
func (r Role) Valid() bool {
	switch r {
	case RoleOwner, RoleAdmin, RoleBilling, RoleMember, RoleViewer:
		return true
	}
	return false
}

// Member is a user's membership of an organization.
type Member struct {
	OrgID     string    `json:"org_id"`
	UserID    string    `json:"user_id"`
	Role      Role      `json:"role"`
	CreatedAt time.Time `json:"created_at"`
}

// APIKey lets a member call the API. It acts as that member, with the member's current role.
type APIKey struct {
	ID         string     `json:"id"`
	OrgID      string     `json:"org_id"`
	UserID     string     `json:"user_id"`
	Name       string     `json:"name"`
	Token      string     `json:"token"`
	CreatedAt  time.Time  `json:"created_at"`
	LastUsedAt *time.Time `json:"last_used_at,omitempty"`
	RevokedAt  *time.Time `json:"revoked_at,omitempty"`
}

// Invite asks someone to join an organization. Its token is sent to the invited address.
type Invite struct {
	ID         string     `json:"id"`
	OrgID      string     `json:"org_id"`
	Email      string     `json:"email"`
	Role       Role       `json:"role"`
	Token      string     `json:"token"`
	InvitedBy  string     `json:"invited_by"`
	CreatedAt  time.Time  `json:"created_at"`
	AcceptedAt *time.Time `json:"accepted_at,omitempty"`
	RevokedAt  *time.Time `json:"revoked_at,omitempty"`
}

// Customer is one of an organization's customers.
type Customer struct {
	ID    string `json:"id"`
	OrgID string `json:"org_id"`
	Name  string `json:"name"`
	Email string `json:"email"`
	// DefaultPaymentMethod is charged for renewals ("pm_..."); empty means invoices wait to be paid by hand.
	DefaultPaymentMethod string            `json:"default_payment_method,omitempty"`
	Metadata             map[string]string `json:"metadata,omitempty"`
	CreatedAt            time.Time         `json:"created_at"`
}

// Interval is how often a plan bills.
type Interval string

// Intervals.
const (
	Monthly Interval = "month"
	Yearly  Interval = "year"
)

// UsageType says what a plan charges for.
type UsageType string

// Usage types.
const (
	// Licensed plans charge UnitAmount per seat (the subscription's quantity) at the start of each period.
	Licensed UsageType = "licensed"
	// Metered plans charge UnitAmount per unit of reported usage at the end of each period.
	Metered UsageType = "metered"
)

// Plan is something an organization sells to its customers.
type Plan struct {
	ID         string         `json:"id"`
	OrgID      string         `json:"org_id"`
	Name       string         `json:"name"`
	Currency   money.Currency `json:"currency"`
	UnitAmount int64          `json:"unit_amount"` // minor units
	Interval   Interval       `json:"interval"`
	UsageType  UsageType      `json:"usage_type"`
	TrialDays  int            `json:"trial_days"`
	Active     bool           `json:"active"`
	CreatedAt  time.Time      `json:"created_at"`
}

// SubStatus is a subscription's state.
type SubStatus string

// Subscription states.
const (
	Trialing SubStatus = "trialing"
	Active   SubStatus = "active"
	PastDue  SubStatus = "past_due"
	Canceled SubStatus = "canceled"
)

// Subscription is a customer's subscription to a plan.
type Subscription struct {
	ID              string    `json:"id"`
	OrgID           string    `json:"org_id"`
	CustomerID      string    `json:"customer_id"`
	PlanID          string    `json:"plan_id"`
	Quantity        int       `json:"quantity"`
	Status          SubStatus `json:"status"`
	DiscountPercent int       `json:"discount_percent"`
	// StartedAt is when the subscription began; its billing periods are counted from it.
	StartedAt          time.Time  `json:"started_at"`
	CurrentPeriodStart time.Time  `json:"current_period_start"`
	CurrentPeriodEnd   time.Time  `json:"current_period_end"`
	TrialEnd           *time.Time `json:"trial_end,omitempty"`
	CancelAtPeriodEnd  bool       `json:"cancel_at_period_end"`
	CanceledAt         *time.Time `json:"canceled_at,omitempty"`
	CreatedAt          time.Time  `json:"created_at"`
}

// Line is one line of an invoice. A negative UnitAmount is a credit.
type Line struct {
	Description string `json:"description"`
	Quantity    int64  `json:"quantity"`
	UnitAmount  int64  `json:"unit_amount"`
}

// Amount is the line's quantity times its unit amount.
func (l Line) Amount() int64 { return l.Quantity * l.UnitAmount }

// InvoiceStatus is an invoice's state.
type InvoiceStatus string

// Invoice states.
const (
	InvoiceOpen InvoiceStatus = "open"
	InvoicePaid InvoiceStatus = "paid"
	InvoiceVoid InvoiceStatus = "void"
)

// Invoice is a bill to a customer.
type Invoice struct {
	ID              string         `json:"id"`
	OrgID           string         `json:"org_id"`
	CustomerID      string         `json:"customer_id"`
	SubscriptionID  string         `json:"subscription_id,omitempty"`
	Currency        money.Currency `json:"currency"`
	Lines           []Line         `json:"lines"`
	DiscountPercent int            `json:"discount_percent"`
	TaxRateBP       int            `json:"tax_rate_bp"`
	Status          InvoiceStatus  `json:"status"`
	PeriodStart     *time.Time     `json:"period_start,omitempty"`
	PeriodEnd       *time.Time     `json:"period_end,omitempty"`
	CreatedAt       time.Time      `json:"created_at"`
	PaidAt          *time.Time     `json:"paid_at,omitempty"`
	VoidedAt        *time.Time     `json:"voided_at,omitempty"`
}

// PaymentStatus is a payment attempt's result.
type PaymentStatus string

// Payment results.
const (
	PaymentSucceeded PaymentStatus = "succeeded"
	PaymentFailed    PaymentStatus = "failed"
)

// Payment is one attempt to charge an invoice.
type Payment struct {
	ID          string         `json:"id"`
	OrgID       string         `json:"org_id"`
	InvoiceID   string         `json:"invoice_id"`
	Amount      int64          `json:"amount"`
	Currency    money.Currency `json:"currency"`
	Status      PaymentStatus  `json:"status"`
	FailureCode string         `json:"failure_code,omitempty"`
	GatewayRef  string         `json:"gateway_ref,omitempty"`
	CreatedAt   time.Time      `json:"created_at"`
}

// UsageRecord is usage reported for a subscription to a metered plan.
type UsageRecord struct {
	ID             string    `json:"id"`
	OrgID          string    `json:"org_id"`
	SubscriptionID string    `json:"subscription_id"`
	Quantity       int64     `json:"quantity"`
	At             time.Time `json:"at"`
	CreatedAt      time.Time `json:"created_at"`
}

// WebhookEndpoint is a URL of the organization's that receives events.
type WebhookEndpoint struct {
	ID     string   `json:"id"`
	OrgID  string   `json:"org_id"`
	URL    string   `json:"url"`
	Events []string `json:"events"` // event types, or "*" for all
	// Secret signs the deliveries (webhooks.Sign).
	Secret         string    `json:"secret"`
	Enabled        bool      `json:"enabled"`
	DisabledReason string    `json:"disabled_reason,omitempty"`
	CreatedAt      time.Time `json:"created_at"`
}

// Event is something that happened in an organization, sent to its webhook endpoints.
type Event struct {
	ID        string          `json:"id"`
	OrgID     string          `json:"org_id"`
	Type      string          `json:"type"`
	Data      json.RawMessage `json:"data"`
	CreatedAt time.Time       `json:"created_at"`
}

// DeliveryStatus is a webhook delivery's state.
type DeliveryStatus string

// Delivery states.
const (
	DeliveryPending   DeliveryStatus = "pending"
	DeliverySucceeded DeliveryStatus = "succeeded"
	DeliveryFailed    DeliveryStatus = "failed"
)

// Delivery is the sending of one event to one endpoint.
type Delivery struct {
	ID             string         `json:"id"`
	OrgID          string         `json:"org_id"`
	EndpointID     string         `json:"endpoint_id"`
	EventID        string         `json:"event_id"`
	Status         DeliveryStatus `json:"status"`
	Attempts       int            `json:"attempts"`
	NextAttemptAt  *time.Time     `json:"next_attempt_at,omitempty"`
	LastAttemptAt  *time.Time     `json:"last_attempt_at,omitempty"`
	ResponseStatus int            `json:"response_status,omitempty"`
	Error          string         `json:"error,omitempty"`
	CreatedAt      time.Time      `json:"created_at"`
}
package store

import (
	"fmt"
	"sort"
)

// State is everything a store holds, for snapshots (package snapshot). Slices are sorted by ID.
type State struct {
	Seq              int               `json:"seq"`
	Orgs             []Org             `json:"orgs"`
	Users            []User            `json:"users"`
	Members          []Member          `json:"members"`
	APIKeys          []APIKey          `json:"api_keys"`
	Invites          []Invite          `json:"invites"`
	Customers        []Customer        `json:"customers"`
	Plans            []Plan            `json:"plans"`
	Subscriptions    []Subscription    `json:"subscriptions"`
	Usage            []UsageRecord     `json:"usage"`
	Invoices         []Invoice         `json:"invoices"`
	Payments         []Payment         `json:"payments"`
	WebhookEndpoints []WebhookEndpoint `json:"webhook_endpoints"`
	Events           []Event           `json:"events"`
	Deliveries       []Delivery        `json:"deliveries"`
}

// Export returns a copy of everything in the store.
func (s *Store) Export() State {
	s.mu.Lock()
	defer s.mu.Unlock()
	st := State{Seq: s.seq}
	for _, o := range s.orgs {
		st.Orgs = append(st.Orgs, o)
	}
	for _, u := range s.users {
		st.Users = append(st.Users, u)
	}
	for _, m := range s.members {
		st.Members = append(st.Members, m)
	}
	for _, k := range s.apiKeys {
		st.APIKeys = append(st.APIKeys, k)
	}
	for _, i := range s.invites {
		st.Invites = append(st.Invites, i)
	}
	for _, c := range s.customers {
		st.Customers = append(st.Customers, copyCustomer(c))
	}
	for _, p := range s.plans {
		st.Plans = append(st.Plans, p)
	}
	for _, sub := range s.subs {
		st.Subscriptions = append(st.Subscriptions, copySub(sub))
	}
	st.Usage = append(st.Usage, s.usage...)
	for _, inv := range s.invoices {
		st.Invoices = append(st.Invoices, copyInvoice(inv))
	}
	for _, p := range s.payments {
		st.Payments = append(st.Payments, p)
	}
	for _, ep := range s.endpoints {
		st.WebhookEndpoints = append(st.WebhookEndpoints, copyEndpoint(ep))
	}
	for _, e := range s.events {
		st.Events = append(st.Events, e)
	}
	for _, d := range s.delivs {
		st.Deliveries = append(st.Deliveries, copyDelivery(d))
	}
	sort.Slice(st.Orgs, func(i, j int) bool { return st.Orgs[i].ID < st.Orgs[j].ID })
	sort.Slice(st.Users, func(i, j int) bool { return st.Users[i].ID < st.Users[j].ID })
	sort.Slice(st.Members, func(i, j int) bool {
		if st.Members[i].OrgID != st.Members[j].OrgID {
			return st.Members[i].OrgID < st.Members[j].OrgID
		}
		return st.Members[i].UserID < st.Members[j].UserID
	})
	sort.Slice(st.APIKeys, func(i, j int) bool { return st.APIKeys[i].ID < st.APIKeys[j].ID })
	sort.Slice(st.Invites, func(i, j int) bool { return st.Invites[i].ID < st.Invites[j].ID })
	sort.Slice(st.Customers, func(i, j int) bool { return st.Customers[i].ID < st.Customers[j].ID })
	sort.Slice(st.Plans, func(i, j int) bool { return st.Plans[i].ID < st.Plans[j].ID })
	sort.Slice(st.Subscriptions, func(i, j int) bool { return st.Subscriptions[i].ID < st.Subscriptions[j].ID })
	sort.Slice(st.Usage, func(i, j int) bool { return st.Usage[i].ID < st.Usage[j].ID })
	sort.Slice(st.Invoices, func(i, j int) bool { return st.Invoices[i].ID < st.Invoices[j].ID })
	sort.Slice(st.Payments, func(i, j int) bool { return st.Payments[i].ID < st.Payments[j].ID })
	sort.Slice(st.WebhookEndpoints, func(i, j int) bool { return st.WebhookEndpoints[i].ID < st.WebhookEndpoints[j].ID })
	sort.Slice(st.Events, func(i, j int) bool { return st.Events[i].ID < st.Events[j].ID })
	sort.Slice(st.Deliveries, func(i, j int) bool { return st.Deliveries[i].ID < st.Deliveries[j].ID })
	return st
}

// FromState builds a store holding st.
func FromState(st State) (*Store, error) {
	s := New()
	s.seq = st.Seq
	dup := func(kind, id string, seen map[string]bool) error {
		if id == "" || seen[id] {
			return fmt.Errorf("%w: %s %q is missing or repeated", ErrInvalid, kind, id)
		}
		seen[id] = true
		return nil
	}
	seen := map[string]bool{}
	for _, o := range st.Orgs {
		if err := dup("organization", o.ID, seen); err != nil {
			return nil, err
		}
		s.orgs[o.ID] = o
	}
	for _, u := range st.Users {
		if err := dup("user", u.ID, seen); err != nil {
			return nil, err
		}
		s.users[u.ID] = u
		s.usersByEmail[normEmail(u.Email)] = u.ID
	}
	for _, m := range st.Members {
		if _, ok := s.orgs[m.OrgID]; !ok {
			return nil, fmt.Errorf("%w: member of unknown organization %q", ErrInvalid, m.OrgID)
		}
		if _, ok := s.users[m.UserID]; !ok {
			return nil, fmt.Errorf("%w: member is unknown user %q", ErrInvalid, m.UserID)
		}
		s.members[memberKey{m.OrgID, m.UserID}] = m
	}
	for _, k := range st.APIKeys {
		if err := dup("API key", k.ID, seen); err != nil {
			return nil, err
		}
		s.apiKeys[k.ID] = k
		if k.Token != "" {
			s.keysByToken[k.Token] = k.ID
		}
	}
	for _, i := range st.Invites {
		if err := dup("invite", i.ID, seen); err != nil {
			return nil, err
		}
		s.invites[i.ID] = i
	}
	for _, c := range st.Customers {
		if err := dup("customer", c.ID, seen); err != nil {
			return nil, err
		}
		s.customers[c.ID] = copyCustomer(c)
		s.customersByEmail[normEmail(c.Email)] = c.ID
	}
	for _, p := range st.Plans {
		if err := dup("plan", p.ID, seen); err != nil {
			return nil, err
		}
		s.plans[p.ID] = p
	}
	for _, sub := range st.Subscriptions {
		if err := dup("subscription", sub.ID, seen); err != nil {
			return nil, err
		}
		s.subs[sub.ID] = copySub(sub)
	}
	s.usage = append(s.usage, st.Usage...)
	for _, inv := range st.Invoices {
		if err := dup("invoice", inv.ID, seen); err != nil {
			return nil, err
		}
		s.invoices[inv.ID] = copyInvoice(inv)
	}
	for _, p := range st.Payments {
		if err := dup("payment", p.ID, seen); err != nil {
			return nil, err
		}
		s.payments[p.ID] = p
	}
	for _, ep := range st.WebhookEndpoints {
		if err := dup("webhook endpoint", ep.ID, seen); err != nil {
			return nil, err
		}
		s.endpoints[ep.ID] = copyEndpoint(ep)
	}
	for _, e := range st.Events {
		if err := dup("event", e.ID, seen); err != nil {
			return nil, err
		}
		s.events[e.ID] = e
	}
	for _, d := range st.Deliveries {
		if err := dup("delivery", d.ID, seen); err != nil {
			return nil, err
		}
		s.delivs[d.ID] = copyDelivery(d)
	}
	return s, nil
}
package api

import (
	"errors"
	"fmt"
	"net/http"
	"strings"

	"example.com/tally/internal/auth"
	"example.com/tally/internal/billing"
	"example.com/tally/internal/money"
	"example.com/tally/internal/payments"
	"example.com/tally/internal/store"
)

// invoiceView is an invoice as the API shows it: with its totals, a one-line description and its customer.
type invoiceView struct {
	store.Invoice
	billing.Totals
	TotalFormatted string       `json:"total_formatted"`
	Description    string       `json:"description"`
	Customer       *customerRef `json:"customer"`
}

// customerRef is the customer shown on an invoice; null when the customer was deleted.
type customerRef struct {
	ID    string `json:"id"`
	Name  string `json:"name"`
	Email string `json:"email"`
}

func newInvoiceView(inv store.Invoice, c *store.Customer) invoiceView {
	t := billing.Compute(inv)
	v := invoiceView{Invoice: inv, Totals: t, TotalFormatted: money.Format(t.Total, inv.Currency), Description: describe(inv.Lines)}
	if c != nil {
		v.Customer = &customerRef{ID: c.ID, Name: c.Name, Email: c.Email}
	}
	return v
}

// describe is the invoice's first line, and how many more there are.
func describe(lines []store.Line) string {
	d := lines[0].Description
	if len(lines) > 1 {
		d += fmt.Sprintf(" and %d more", len(lines)-1)
	}
	return d
}

func (s *Server) viewInvoice(inv store.Invoice) invoiceView {
	if c, ok := s.store.Customer(inv.OrgID, inv.CustomerID); ok {
		return newInvoiceView(inv, &c)
	}
	return newInvoiceView(inv, nil)
}

func findCustomer(cs []store.Customer, id string) *store.Customer {
	for i := range cs {
		if cs[i].ID == id {
			return &cs[i]
		}
	}
	return nil
}

func invoiceViewKey(v invoiceView) cursor { return cursor{T: v.CreatedAt, ID: v.ID} }

// listInvoices lists the organization's invoices, oldest first, optionally only those of ?customer_id=, ?subscription_id=
// or with ?status=.
func (s *Server) listInvoices(w http.ResponseWriter, r *http.Request, p auth.Principal) {
	pg, ok := parsePage(w, r)
	if !ok {
		return
	}
	q := r.URL.Query()
	status := store.InvoiceStatus(q.Get("status"))
	if status != "" && status != store.InvoiceOpen && status != store.InvoicePaid && status != store.InvoiceVoid {
		writeError(w, http.StatusBadRequest, "invalid_status", "status is open, paid or void")
		return
	}
	invs := s.store.ListInvoices(p.OrgID, store.InvoiceFilter{CustomerID: q.Get("customer_id"), SubscriptionID: q.Get("subscription_id"), Status: status})
	customers := s.store.Customers(p.OrgID)
	views := make([]invoiceView, 0, len(invs))
	for _, inv := range invs {
		views = append(views, newInvoiceView(inv, findCustomer(customers, inv.CustomerID)))
	}
	items, next := pageOf(views, invoiceViewKey, pg)
	writeJSON(w, http.StatusOK, list{Items: items, NextCursor: next})
}

func (s *Server) createInvoice(w http.ResponseWriter, r *http.Request, p auth.Principal) {
	var in struct {
		CustomerID      string         `json:"customer_id"`
		Currency        money.Currency `json:"currency"`
		Lines           []store.Line   `json:"lines"`
		DiscountPercent int            `json:"discount_percent"`
	}
	if !decode(w, r, &in) {
		return
	}
	if len(in.Lines) == 0 {
		writeError(w, http.StatusUnprocessableEntity, "invalid", "an invoice needs at least one line")
		return
	}
	for _, l := range in.Lines {
		if strings.TrimSpace(l.Description) == "" || l.Quantity <= 0 || l.UnitAmount < 0 {
			writeError(w, http.StatusUnprocessableEntity, "invalid", "each line needs a description, a positive quantity and a unit amount that is not negative")
			return
		}
	}
	inv, err := s.store.CreateInvoice(store.Invoice{OrgID: p.OrgID, CustomerID: in.CustomerID, Currency: in.Currency, Lines: in.Lines, DiscountPercent: in.DiscountPercent}, s.clock.Now())
	if err != nil {
		if errors.Is(err, store.ErrCustomerOrgMismatch) {
			writeError(w, http.StatusUnprocessableEntity, "customer_org_mismatch", fmt.Sprintf("customer %s belongs to another organization", in.CustomerID))
			return
		}
		s.storeError(w, err)
		return
	}
	s.publish(r.Context(), p.OrgID, "invoice.created", map[string]any{"invoice_id": inv.ID})
	writeJSON(w, http.StatusCreated, s.viewInvoice(inv))
}

func (s *Server) getInvoice(w http.ResponseWriter, r *http.Request, p auth.Principal) {
	inv, ok := s.store.Invoice(p.OrgID, r.PathValue("id"))
	if !ok {
		writeError(w, http.StatusNotFound, "not_found", "no such invoice")
		return
	}
	writeJSON(w, http.StatusOK, s.viewInvoice(inv))
}

// getInvoiceLines answers an invoice's lines with each line's amount, for the dashboard's invoice table.
func (s *Server) getInvoiceLines(w http.ResponseWriter, r *http.Request, p auth.Principal) {
	inv, ok := s.store.InvoiceByID(r.PathValue("id"))
	if !ok {
		writeError(w, http.StatusNotFound, "not_found", "no such invoice")
		return
	}
	type lineView struct {
		store.Line
		Amount int64 `json:"amount"`
	}
	items := []lineView{}
	for _, l := range inv.Lines {
		items = append(items, lineView{Line: l, Amount: l.Amount()})
	}
	writeJSON(w, http.StatusOK, list{Items: items})
}

// payInvoice charges an invoice: {"payment_method": "pm_..."}, or the customer's default payment method when it is absent.
func (s *Server) payInvoice(w http.ResponseWriter, r *http.Request, p auth.Principal) {
	var in struct {
		PaymentMethod string `json:"payment_method"`
	}
	if r.ContentLength != 0 && !decode(w, r, &in) {
		return
	}
	inv, pay, err := s.pay.Pay(r.Context(), p.OrgID, r.PathValue("id"), in.PaymentMethod)
	if err != nil {
		s.payError(w, err)
		return
	}
	writeJSON(w, http.StatusOK, map[string]any{"invoice": s.viewInvoice(inv), "payment": pay})
}

func (s *Server) payError(w http.ResponseWriter, err error) {
	var decline *payments.DeclineError
	switch {
	case errors.As(err, &decline):
		writeJSON(w, http.StatusPaymentRequired, map[string]string{"error": "payment_declined", "decline_code": decline.Code, "message": err.Error()})
	case errors.Is(err, payments.ErrAlreadyPaid):
		writeError(w, http.StatusConflict, "already_paid", err.Error())
	case errors.Is(err, payments.ErrInvoiceVoid):
		writeError(w, http.StatusConflict, "invoice_void", err.Error())
	case errors.Is(err, payments.ErrNoPaymentMethod):
		writeError(w, http.StatusUnprocessableEntity, "no_payment_method", err.Error())
	case errors.Is(err, payments.ErrUnavailable):
		writeError(w, http.StatusServiceUnavailable, "gateway_unavailable", "the payment gateway is unavailable; nothing was charged, try again")
	default:
		s.storeError(w, err)
	}
}

func (s *Server) voidInvoice(w http.ResponseWriter, r *http.Request, p auth.Principal) {
	now := s.clock.Now()
	inv, err := s.store.UpdateInvoice(p.OrgID, r.PathValue("id"), func(inv *store.Invoice) error {
		switch inv.Status {
		case store.InvoicePaid:
			return payments.ErrAlreadyPaid
		case store.InvoiceVoid:
			return payments.ErrInvoiceVoid
		}
		inv.Status, inv.VoidedAt = store.InvoiceVoid, &now
		return nil
	})
	if err != nil {
		s.payError(w, err)
		return
	}
	s.publish(r.Context(), p.OrgID, "invoice.voided", map[string]any{"invoice_id": inv.ID})
	writeJSON(w, http.StatusOK, s.viewInvoice(inv))
}

func (s *Server) listPayments(w http.ResponseWriter, r *http.Request, p auth.Principal) {
	writeJSON(w, http.StatusOK, list{Items: s.store.Payments(p.OrgID, r.URL.Query().Get("invoice_id"))})
}

package store

import (
	"encoding/json"
	"sort"
	"strings"
	"time"
)

// ---- plans

// CreatePlan adds a plan. UsageType defaults to Licensed; a new plan is active.
func (s *Store) CreatePlan(p Plan, now time.Time) (Plan, error) {
	p.Name = strings.TrimSpace(p.Name)
	if p.UsageType == "" {
		p.UsageType = Licensed
	}
	p.Active = true
	if err := checkPlan(p); err != nil {
		return Plan{}, err
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	if _, ok := s.orgs[p.OrgID]; !ok {
		return Plan{}, ErrNotFound
	}
	p.ID = s.newID("plan")
	p.CreatedAt = now.UTC()
	s.plans[p.ID] = p
	return p, nil
}

func checkPlan(p Plan) error {
	switch {
	case p.Name == "":
		return invalid("a plan needs a name")
	case !p.Currency.Valid():
		return invalid("unknown currency %q", p.Currency)
	case p.UnitAmount < 0:
		return invalid("a plan's price cannot be negative")
	case p.Interval != Monthly && p.Interval != Yearly:
		return invalid("a plan bills every month or every year")
	case p.UsageType != Licensed && p.UsageType != Metered:
		return invalid("a plan is licensed or metered")
	case p.TrialDays < 0 || p.TrialDays > 365:
		return invalid("a trial lasts 0 to 365 days")
	}
	return nil
}

// Plan returns one of an organization's plans.
func (s *Store) Plan(orgID, id string) (Plan, bool) {
	s.mu.Lock()
	defer s.mu.Unlock()
	p, ok := s.plans[id]
	if !ok || p.OrgID != orgID {
		return Plan{}, false
	}
	return p, true
}

// Plans returns an organization's plans, oldest first.
func (s *Store) Plans(orgID string) []Plan {
	s.mu.Lock()
	defer s.mu.Unlock()
	out := []Plan{}
	for _, p := range s.plans {
		if p.OrgID == orgID {
			out = append(out, p)
		}
	}
	sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
	return out
}

// UpdatePlan changes a plan with f. Its currency, price, interval and usage type cannot change once created: subscriptions
// depend on them.
func (s *Store) UpdatePlan(orgID, id string, f func(*Plan) error) (Plan, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	old, ok := s.plans[id]
	if !ok || old.OrgID != orgID {
		return Plan{}, ErrNotFound
	}
	p := old
	if err := f(&p); err != nil {
		return Plan{}, err
	}
	p.ID, p.OrgID, p.CreatedAt = old.ID, old.OrgID, old.CreatedAt
	p.Currency, p.UnitAmount, p.Interval, p.UsageType = old.Currency, old.UnitAmount, old.Interval, old.UsageType
	p.Name = strings.TrimSpace(p.Name)
	if err := checkPlan(p); err != nil {
		return Plan{}, err
	}
	s.plans[id] = p
	return p, nil
}

// ---- subscriptions

// CreateSubscription stores a new subscription. The caller sets its status and periods.
func (s *Store) CreateSubscription(sub Subscription, now time.Time) (Subscription, error) {
	if sub.Quantity <= 0 {
		return Subscription{}, invalid("the quantity must be at least 1")
	}
	if sub.DiscountPercent < 0 || sub.DiscountPercent > 100 {
		return Subscription{}, invalid("the discount is 0 to 100 percent")
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	if _, ok := s.customers[sub.CustomerID]; !ok {
		return Subscription{}, ErrNotFound
	}
	if p, ok := s.plans[sub.PlanID]; !ok || p.OrgID != sub.OrgID {
		return Subscription{}, ErrNotFound
	}
	sub.ID = s.newID("sub")
	sub.CreatedAt = now.UTC()
	s.subs[sub.ID] = sub
	return copySub(sub), nil
}

// Subscription returns one of an organization's subscriptions.
func (s *Store) Subscription(orgID, id string) (Subscription, bool) {
	s.mu.Lock()
	defer s.mu.Unlock()
	sub, ok := s.subs[id]
	if !ok || sub.OrgID != orgID {
		return Subscription{}, false
	}
	return copySub(sub), true
}

// SubscriptionFilter narrows Subscriptions.
type SubscriptionFilter struct {
	CustomerID string
	Status     SubStatus
}

// Subscriptions returns an organization's subscriptions that match f, oldest first.
func (s *Store) Subscriptions(orgID string, f SubscriptionFilter) []Subscription {
	s.mu.Lock()
	defer s.mu.Unlock()
	out := []Subscription{}
	for _, sub := range s.subs {
		if sub.OrgID != orgID || (f.CustomerID != "" && sub.CustomerID != f.CustomerID) || (f.Status != "" && sub.Status != f.Status) {
			continue
		}
		out = append(out, copySub(sub))
	}
	sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
	return out
}

// UpdateSubscription changes a subscription with f, which may refuse with an error.
func (s *Store) UpdateSubscription(orgID, id string, f func(*Subscription) error) (Subscription, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	old, ok := s.subs[id]
	if !ok || old.OrgID != orgID {
		return Subscription{}, ErrNotFound
	}
	sub := copySub(old)
	if err := f(&sub); err != nil {
		return Subscription{}, err
	}
	sub.ID, sub.OrgID, sub.CustomerID, sub.CreatedAt = old.ID, old.OrgID, old.CustomerID, old.CreatedAt
	if sub.Quantity <= 0 {
		return Subscription{}, invalid("the quantity must be at least 1")
	}
	if p, ok := s.plans[sub.PlanID]; !ok || p.OrgID != orgID {
		return Subscription{}, ErrNotFound
	}
	s.subs[id] = sub
