func TestUpgradeKeepsBackupOfOlderVersions(t *testing.T) {
	v1, err := os.ReadFile(filepath.Join("testdata", "v1.json"))
	if err != nil {
		t.Fatal(err)
	}
	for _, c := range []struct {
		version int
		content []byte
	}{{1, v1}, {2, []byte(v2Snapshot)}} {
		path := writeFile(t, c.content)
		before, err := Load(path)
		if err != nil {
			t.Fatal(err)
		}
		if err := Upgrade(path); err != nil {
			t.Fatalf("version %d: %v", c.version, err)
		}
		bak, err := os.ReadFile(fmt.Sprintf("%s.v%d.bak", path, c.version))
		if err != nil || !bytes.Equal(bak, c.content) {
			t.Fatalf("version %d: the backup is not the original file: %v", c.version, err)
		}
		if v := fileVersion(t, path); v != Version {
			t.Fatalf("version %d: upgraded to version %d, want %d", c.version, v, Version)
		}
		after, err := Load(path)
		if err != nil {
			t.Fatal(err)
		}
		if !reflect.DeepEqual(after.Export(), before.Export()) {
			t.Fatalf("version %d: the upgrade changed the data", c.version)
		}
		if err := Upgrade(path); err != nil {
			t.Fatal(err)
		}
		if n := dirEntries(t, path); n != 2 {
			t.Fatalf("version %d: the folder has %d entries, want the snapshot and its backup", c.version, n)
		}
	}
}

